  async function save(e){e.preventDefault();if(uploading){setUploadError('Please wait until image uploads finish before saving.');return}setBusy(true);setError('');setNotice('');const payload={...form,price:Number(form.price),compareAtPrice:form.compareAtPrice===''?undefined:Number(form.compareAtPrice),variantStocks:form.variantStocks.split('\n').map(line=>{const [size,color,stock]=line.split('|').map(x=>x.trim());return {size,color,stock:Number(stock)}}).filter(v=>v.size&&v.color&&Number.isInteger(v.stock)&&v.stock>=0),stock:Number(form.stock),category:form.category||undefined,sizes:form.sizes.split(',').map(x=>x.trim()).filter(Boolean),colors:form.colors.split(',').map(x=>x.trim()).filter(Boolean),images:form.images.filter(Boolean),tags:form.tags.split(',').map(x=>x.trim()).filter(Boolean)};try{if(!payload.name||!Number.isFinite(payload.price)||payload.price<0||!Number.isFinite(payload.stock)||payload.stock<0)throw new Error('Enter a product name, a valid price and a non-negative stock quantity.');if(editing)await updateProduct(editing,payload);else await createProduct(payload);const wasEditing=Boolean(editing);close();setNotice(wasEditing?'Product details updated.':'Product added successfully.');await load()}catch(e){setError(e.response?.data?.message||'Product could not be saved. Check the details and image URLs.')}finally{setBusy(false)}}
