 async function load(){setBusy(true);setError('');try{const {data}=await api.get('/products/admin/all');setItems(data||[])}catch(e){setError(e.response?.data?.message||'Could not load inventory. Sign in with an authorized admin account.')}finally{setBusy(false)}}
