 if(page==='language')return <><div className="admin-welcome"><div><span className="eyebrow">LOCALISATION</span><h1>{title}</h1><p>Choose the preferred language for the admin workspace.</p></div></div><div className="admin-panel"><label>Workspace language<select value={localStorage.getItem('so-admin-language')||'en'} onChange={e=>{localStorage.setItem('so-admin-language',e.target.value);setNotice('Language preference saved for this browser.')}}><option value="en">English</option></select></label>{notice&&<p className="admin-success">{notice}</p>}<p className="muted">This preference currently applies to this browser only; storefront-wide translation is not enabled yet.</p></div></>
